// The chapter reader's books, built from files (used by index.mjs, which writes them, and check_books.mjs, which
// proves what is committed is what the files say). A book is a folder reader/content/c<NN>/<subject>/ holding:
//   book.json   written by hand: { "id": "ncert.jesc1", "boards": ["CBSE"], "catalog": { "board": "CBSE", "chapters": { "1": "cbse.c10..." } } }
//   <key>.json  one file per chapter, from the content team
//   index.json  GENERATED by index.mjs (never edited)
// plus the generated reader/content/books.json, which lists every book index (the Family app reads this one).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const READER = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const ROOT = path.resolve(READER, '..');
const readJson = (f) => JSON.parse(fs.readFileSync(f, 'utf8'));
const dirs = (d) => (fs.existsSync(d) ? fs.readdirSync(d, { withFileTypes: true }).filter((e) => e.isDirectory()).map((e) => e.name).sort() : []);

// Every book folder under a content root: [{ cls, subject, dir, rel, files }]. A folder counts when it holds book.json or a chapter file.
export function bookFolders(root = path.join(READER, 'content')) {
  const out = [];
  for (const c of dirs(root).filter((d) => /^c\d\d$/.test(d))) {
    for (const s of dirs(path.join(root, c))) {
      const dir = path.join(root, c, s);
      const files = fs.readdirSync(dir);
      if (files.includes('book.json') || files.some((f) => /^u\..*\.json$/.test(f))) out.push({ cls: c, subject: s, dir, rel: `${c}/${s}`, files });
    }
  }
  return out;
}

// One book's index from its folder, the lab defs (the syllabus: a planned chapter has no reader file yet) and book.json.
export function buildBook(folder, { labsRoot = path.join(ROOT, 'labs/defs') } = {}) {
  const meta = readJson(path.join(folder.dir, 'book.json'));
  const code = String(meta.id).split('.')[1];
  const defsDir = path.join(labsRoot, folder.cls, folder.subject);
  const re = new RegExp(`^u\\.${folder.cls}\\.${folder.subject}\\.${code}\\.ch\\d\\d\\.json$`);
  const catalog = (meta.catalog && meta.catalog.chapters) || {};
  const chapters = (fs.existsSync(defsDir) ? fs.readdirSync(defsDir) : []).filter((f) => re.test(f)).sort().map((f) => {
    const def = readJson(path.join(defsDir, f));
    const number = +f.match(/ch(\d\d)/)[1];
    const rel = `${folder.rel}/${f}`;
    const out = { key: def.chapter_key, number, title: { en: def.title, hi: def.title }, file: null, topics: 0, minutes: 0, image: null, topic_titles: [], catalog_key: catalog[number] ?? null };
    const real = path.join(folder.dir, f);
    if (fs.existsSync(real)) {
      const ch = readJson(real);
      Object.assign(out, { title: ch.title, file: rel, topics: ch.topics.length, minutes: ch.minutes || ch.topics.reduce((a, t) => a + (t.minutes || 0), 0), image: (ch.hook && ch.hook.image) || null, topic_titles: ch.topics.map((t) => t.title) });
    }
    return out;
  });
  return { id: meta.id, class: +folder.cls.slice(1), subject_id: folder.subject, boards: meta.boards, catalog_board: (meta.catalog && meta.catalog.board) || null, chapters };
}

export const serialize = (x) => JSON.stringify(x, null, 1) + '\n';

// Everything index.mjs writes, as { path under the content root: text }, and the books.
export function buildAll(root = path.join(READER, 'content'), opts) {
  const files = {};
  const books = [];
  for (const f of bookFolders(root)) {
    if (!f.files.includes('book.json')) continue; // check_books.mjs reports it
    const b = buildBook(f, opts);
    files[`${f.rel}/index.json`] = serialize(b);
    books.push(b);
  }
  books.sort((a, b) => a.class - b.class || a.subject_id.localeCompare(b.subject_id));
  files['books.json'] = serialize({ books });
  return { files, books };
}
